=== file: main.loom ===
budget { tokens: 12000  calls: 8 }

tool OvernightLogFeed {
    use: http
    base_url: env.OVERNIGHT_LOG_URL
    auth_header: "Authorization"
    auth_value: env.OVERNIGHT_LOG_TOKEN
    allow_paths: "/overnight/errors"
    methods: "GET"
}

tool OnCallChannel {
    use: webhook
    url: env.ONCALL_CHANNEL_WEBHOOK
    format: slack
}

agent LogReader {
    model: "gpt-6-luna"
    prompt: "log_reader"
    tools: [OvernightLogFeed]
    temperature: 0.1
    guard { pii: mask }
    budget { tokens: 12000 per day when_exhausted: stop }
    output_schema: {
        lines: list<string>,
        truncated: enum["YES", "NO"]
    }
}

agent ReportBuilder {
    model: "gpt-6-luna"
    prompt: "morning_report"
    temperature: 0.2
    guard { pii: mask }
    budget { tokens: 12000 per day when_exhausted: stop }
    output_schema: {
        groups: list<string>,
        unclassified: list<string>,
        no_errors: enum["YES", "NO"]
    }
}

agent Publisher {
    model: "gpt-6-luna"
    prompt: "publisher"
    tools: [OnCallChannel]
    temperature: 0.1
    guard { pii: mask }
    budget { tokens: 12000 per day when_exhausted: stop }
    output_schema: {
        status: enum["POSTED"]
    }
}

schedule MorningReport {
    cron: "0 8 * * *"
    timezone: env.ONCALL_TIMEZONE
    run: Main()
    misfire: skip
    overlap: skip
}

workflow Main() {
    set retrieval_state = "ready"

    delegate "Fetch the overnight error lines from the configured feed. Request at most 501 lines so the workflow can detect a feed that exceeds its 500-line limit. Return no more than 500 lines, redacting secrets and personal data. Set truncated to YES if the feed contains more than 500 lines; never silently omit lines." to LogReader -> fetched_overnight_records expecting {
        lines: list<string>,
        truncated: enum["YES", "NO"]
    } retry 2 backoff 2s timeout 30s on_failure {
        set retrieval_state = "failed"
    }

    alt (retrieval_state == "failed") {
        return "FAILED: Overnight log retrieval failed after bounded retries. No report was produced or posted; operator attention is required."
    } else {
        alt (fetched_overnight_records.truncated == "YES") {
            return "FAILED: The overnight feed exceeded the 500-line limit. No partial report was produced or posted; operator attention is required."
        } else {
            set report_state = "ready"

            delegate "Build a concise morning report from these already-redacted log lines. Group lines only when they have a confident shared cause. Put every uncertain line in unclassified and preserve its redacted original wording. If the list is empty, set no_errors to YES and return empty groups and unclassified lists. Lines: {fetched_overnight_records.lines}" to ReportBuilder -> grouped_morning_report expecting {
                groups: list<string>,
                unclassified: list<string>,
                no_errors: enum["YES", "NO"]
            } retry 1 backoff 2s timeout 45s on_failure {
                set report_state = "failed"
            }

            alt (report_state == "failed") {
                return "FAILED: The report could not be produced within the available budget or limits. Nothing was posted; operator attention is required."
            } else {
                set delivery_state = "ready"

                delegate "Post this completed report exactly once to the configured on-call channel. Use a concise heading, include each cause group and its lines, include an Unclassified section with every supplied original redacted line, and use a concise no-errors statement when no_errors is YES. Do not add facts or restore masked data. Report data: {grouped_morning_report}" to Publisher -> channel_delivery_result expecting {
                    status: enum["POSTED"]
                } retry 0 backoff 2s timeout 30s on_failure {
                    set delivery_state = "failed"
                }

                alt (delivery_state == "failed") {
                    return "FAILED: Posting to the on-call channel failed or had an uncertain outcome. No automatic retry was attempted; operator attention is required."
                } else {
                    return "Morning on-call report posted successfully."
                }
            }
        }
    }
